export const typography = {
  // Heading Styles
  h1: {
    fontSize: 28,
    fontWeight: '700',
    lineHeight: 32,
  },
  
  h2: {
    fontSize: 24,
    fontWeight: '700',
    lineHeight: 28,
  },
  
  h3: {
    fontSize: 20,
    fontWeight: '600',
    lineHeight: 24,
  },
  
  h4: {
    fontSize: 18,
    fontWeight: '600',
    lineHeight: 22,
  },
  
  // Body Text
  body: {
    fontSize: 16,
    fontWeight: '400',
    lineHeight: 20,
  },
  
  bodySmall: {
    fontSize: 14,
    fontWeight: '400',
    lineHeight: 18,
  },
  
  // Caption
  caption: {
    fontSize: 12,
    fontWeight: '400',
    lineHeight: 14,
  },
  
  captionBold: {
    fontSize: 12,
    fontWeight: '600',
    lineHeight: 14,
  },
};
